const FONT = 'PingFang SC, Microsoft YaHei, Segoe UI, sans-serif';
const FS = { title:26, body:12.5, note:10 };            // 全图只有这三级字号
const INK = '#121A26', TEXT = '#2C3441', SUB = '#7A8494', CARD_LINE = '#E2E8F2';
const M = 32, TAG_W = 64, TAG_GAP = 8, PAD = 10, GAP = 8, HEAD = 26, FLOW_GAP = 22, IB = 22;
const DEPTH_BG = [null, '#F2F4F8', '#F9FAFC', '#FFFFFF'];  // 明度阶梯：越深越亮
const KINDS = ['dot','sq','ring','tri'];

const isBox = n => Array.isArray(n.children);
const estW = (s, size) => { let w = 0;
  for (const c of String(s)) w += size * (c.charCodeAt(0) > 127 ? 1.0 : 0.56);
  return Math.ceil(w); };
function mix(hex, base, t) {               // t = base 所占比例
  const p = h => [1,3,5].map(i => parseInt(h.slice(i, i+2), 16));
  const a = p(hex), b = p(base);
  return '#' + a.map((v, i) => Math.round(v*(1-t) + b[i]*t).toString(16).padStart(2,'0')).join('');
}

/* ---------- 预处理：继承颜色、计算深度 ---------- */
function prep(n, depth, color, flat, idx) {
  n.depth = depth; n.c = n.color || color || '#5B6B82';
  if (isBox(n)) {
    n.dir = n.dir || 'row';
    const cd = n.bare ? depth : depth + 1;
    n.children.forEach((k, i) => prep(k, cd, n.c, n.flat ?? flat, i));
  } else {
    n.flat = !!flat; n.d = n.d || [];
    n.kind = n.icon === false ? null : (n.icon || KINDS[idx % 4]);
  }
}

/* 横向相邻的带标签关系线：把两者之间的间隙撑到能放下标签 */
function reserveLinkGaps(root) {
  const byId = {}, parent = new Map();
  (function walk(n) { if (n.id) byId[n.id] = n;
    if (isBox(n)) n.children.forEach(k => { parent.set(k, n); walk(k); }); })(root);
  const chain = n => { const a = [n]; while (parent.has(n)) a.unshift(n = parent.get(n)); return a; };
  LINKS.forEach(([a, b, label]) => {
    if (!byId[a] || !byId[b] || !label) return;
    const ca = chain(byId[a]), cb = chain(byId[b]);
    let i = 0; while (ca[i + 1] && ca[i + 1] === cb[i + 1]) i++;
    const lca = ca[i];
    if (!isBox(lca) || lca.dir !== 'row' || lca.wrap || !ca[i+1] || !cb[i+1]) return;
    const ia = lca.children.indexOf(ca[i+1]), ib = lca.children.indexOf(cb[i+1]);
    if (Math.abs(ia - ib) !== 1) return;
    lca.gaps = lca.gaps || {};
    const k = Math.min(ia, ib);
    lca.gaps[k] = Math.max(lca.gaps[k] || GAP, estW(label, FS.note) + 20);
  });
}
const gapAt  = (n, i) => (n.gaps && n.gaps[i]) || (n.flow ? FLOW_GAP : GAP);
const padOf  = n => (n.depth === 0 || n.bare) ? 0 : PAD;
const headOf = n => n.title ? HEAD : 0;
const tagOf  = n => n.tag ? TAG_W + TAG_GAP : 0;
const leafH  = n => n.flat ? 36 : (n.d.length ? 40 + 14 * n.d.length : 40);

/* ---------- 第一遍：自底向上算最小宽度（由文字决定） ---------- */
function minW(n) {
  if (!isBox(n)) {
    const tw = Math.max(estW(n.t, FS.body), ...n.d.map(s => estW(s, FS.note)));
    return n._mw = n.flat ? (n.kind ? IB + 8 : 0) + tw + 20 : 12 + (n.kind ? IB + 9 : 0) + tw + 12;
  }
  const ks = n.children.map(minW);
  const gsum = ks.slice(1).reduce((a, _, i) => a + gapAt(n, i), 0);
  let inner;
  if (n.wrap) {              /* 满行按 wrap 列估宽；整组不足 wrap 个时按实际列数 */
    const cols = Math.floor(ks.length / n.wrap) > 0 ? n.wrap : ks.length;
    inner = cols * Math.max(...ks) + (cols - 1) * (n.flow ? FLOW_GAP : GAP);
  }
  else if (n.dir === 'row') inner = (n.fit || ks.length === 1 || n.children.some(k => k.grow != null))
                                    ? ks.reduce((a, b) => a + b, 0) + gsum
                                    : ks.length * Math.max(...ks) + gsum;      // 等宽要能放下最宽的
  else                      inner = Math.max(...ks);
  if (n.title) inner = Math.max(inner, estW(n.title, FS.body) + 4);
  return n._mw = inner + 2 * padOf(n) + tagOf(n);
}

/* 横排子项宽度：默认等宽（对齐、整齐）；fit:true 按内容；有 grow 按权重 */
function rowWidths(n, bw) {
  const ks = n.children, gsum = ks.slice(1).reduce((a, _, i) => a + gapAt(n, i), 0);
  const avail = bw - gsum;
  const useGrow = ks.some(k => k.grow != null);
  if (!useGrow && !n.fit) {
    const eq = avail / ks.length;
    if (ks.every(k => k._mw <= eq + 0.5)) return ks.map(() => eq);
  }
  const wt = ks.map(k => useGrow ? (k.grow ?? 1) : k._mw);
  const sw = wt.reduce((a, b) => a + b, 0);
  const extra = avail - ks.reduce((a, k) => a + k._mw, 0);
  return ks.map((k, i) => k._mw + extra * wt[i] / sw);
}

/* ---------- 第二遍：自顶向下分配位置 ----------
   minH：父级要求的最小高度 —— 横排里矮的子项被拉伸到同高，
   多出的高度一路分给叶子卡片（内容垂直居中），不会在底部留空洞 */
function layout(n, x, y, w, minH = 0) {
  n.x = x; n.y = y; n.w = w;
  if (!isBox(n)) return n.h = Math.max(leafH(n), minH);
  const p = padOf(n), hd = headOf(n);
  const bx = x + tagOf(n) + p, by = y + p + hd, bw = w - tagOf(n) - 2*p;
  const innerMin = Math.max(0, minH - 2*p - hd);
  const ks = n.children;
  let h;
  if (n.wrap) {
    /* 非 flow：每行铺满整行宽，末行不足 wrap 列时拉伸填满。
       flow 蛇形（boustrophedon）：**固定列宽按 wrap 算**，末行不拉伸——
       各行列对列，行末卡与下行首卡中心必重合 → 回折是纯竖线。
       末行缺的列留在转向远端（奇数行留在左侧），转向侧仍占满。
       列距 FLOW_GAP 给箭头，行距 rg 给竖向连接。 */
    const cg = n.flow ? FLOW_GAP : GAP;
    const rg = n.flow ? 24 : GAP;
    const rows = [];
    for (let r = 0; r * n.wrap < ks.length; r++) rows.push(ks.slice(r * n.wrap, (r + 1) * n.wrap));
    const cwFlow = (bw - (n.wrap - 1) * cg) / n.wrap;   // 固定列宽（按 wrap，不按行内个数）
    const cwOf = row => n.flow ? cwFlow : (bw - (row.length - 1) * cg) / row.length;
    const rh = rows.map(row => Math.max(...row.map(k => layout(k, 0, 0, cwOf(row)))));
    const nat = rh.reduce((a, b) => a + b, 0) + (rows.length - 1) * rg;
    const ex = Math.max(0, innerMin - nat) / rows.length;
    let cy = by;
    rows.forEach((row, r) => {
      const hh = rh[r] + ex, cw = cwOf(row);
      const reverse = n.flow && r % 2 === 1;
      row.forEach((k, i) => {
        /* 偶数行占列 0,1,2…；奇数行从右往左占列 wrap-1,wrap-2…（转向侧对齐） */
        const col = reverse ? (n.wrap - 1 - i) : i;
        layout(k, bx + col * (cw + cg), cy, cw, hh);
      });
      cy += hh + rg;
    });
    h = cy - rg - by;
  } else if (n.dir === 'row') {
    const ws = rowWidths(n, bw);
    const nat = Math.max(...ks.map((k, i) => layout(k, 0, 0, ws[i])));
    h = Math.max(nat, innerMin);
    let cx = bx;
    ks.forEach((k, i) => { layout(k, cx, by, ws[i], h); cx += ws[i] + gapAt(n, i); });
  } else {
    const hs = ks.map(k => layout(k, 0, 0, bw));
    const nat = hs.reduce((a, b) => a + b, 0) + (ks.length - 1) * GAP;
    const ex = Math.max(0, innerMin - nat) / ks.length;
    let cy = by;
    ks.forEach((k, i) => { cy += layout(k, bx, cy, bw, hs[i] + ex) + GAP; });
    h = cy - GAP - by;
  }
  return n.h = h + 2*p + hd;
}

/* ---------- 一致性检查（结果写入 svg.dataset.lint，check.js 读取） ---------- */
function lint(root) {
  const warns = [], leaves = [], name = n => n.title || (n.tag && n.tag[0]) || (n.children[0] && n.children[0].t) || '?';
  (function walk(n) {
    if (!isBox(n)) { leaves.push(n); return; }
    const lk = n.children.filter(k => !isBox(k) && !k.flat);
    if (lk.length > 1 && new Set(lk.map(k => k.d.length > 0)).size > 1)
      warns.push(`「${name(n)}」里有的卡片有说明、有的没有 —— 同组卡片信息量要一致`);
    /* 非流水线横排超限：单行堆太多，画布被拉长。flow 要求相邻不 wrap。红线见 rules-core.mjs */
    if (n.dir === 'row' && !n.wrap && !n.flow && n.children.length > LIMITS.structureRowMax)
      warns.push(`「${name(n)}」非流水线横排 ${n.children.length} 个子项（>${LIMITS.structureRowMax}）—— 用 wrap:N 换行或拆子分组`);
    n.children.forEach(walk);
  })(root);
  if (new Set(leaves.map(l => l.flat)).size > 1)
    warns.push('全图信息深度不统一：有的块是平铺短条（flat），有的是卡片 —— 统一成一种；内容单薄的块先补内容');
  const tops = root.children.filter(k => isBox(k) && !k.bare);
  if (tops.length > 1 && new Set(tops.map(k => !!k.tag)).size > 1)
    warns.push('顶层块有的带 tag、有的不带 —— 统一');
  leaves.forEach(l => { if (typeof l.kind === 'string' && !KINDS.includes(l.kind) && !ICONS[l.kind])
    warns.push(`图标名不存在：${l.kind}（见 references/structure.md 图标清单）`); });
  if (DIAGRAM.lint === false) return [];
  return warns;
}

/* ---------- 计算画布 ---------- */
const root = DIAGRAM.root;
prep(root, 0, null, false, 0);
reserveLinkGaps(root);
const W = DIAGRAM.width || Math.max(960, Math.ceil(minW(root)) + 2*M);
const TOP = DIAGRAM.title ? 100 : M;
layout(root, M, TOP, W - 2*M);
const H = Math.ceil(root.y + root.h + 28);        // 画布高从内容推导

/* ---------- SVG 工具 ---------- */
const NS = 'http://www.w3.org/2000/svg';
const svg = document.getElementById('svg');
svg.setAttribute('width', W); svg.setAttribute('height', H);
svg.setAttribute('viewBox', `0 0 ${W} ${H}`);
Object.assign(document.getElementById('canvas').style, { width: W+'px', height: H+'px' });
const mk = (t, a) => { const e = document.createElementNS(NS, t);
  for (const k in a) e.setAttribute(k, a[k]); return e; };
const add = e => svg.appendChild(e);
const R = (x, y, w, h, fill, r, ex) => add(mk('rect', Object.assign(
  { x, y, width:w, height:h, rx:r, fill, stroke:'none' }, ex || {})));
const TX = (x, y, s, size, fill, weight, anchor) => {
  const t = mk('text', { x, y, 'font-size':size, fill, 'font-weight':weight || 400,
    'text-anchor':anchor || 'start', 'font-family':FONT });
  t.textContent = s; add(t); return t; };
const lintWarns = lint(root);
svg.dataset.kind = 'structure';
if (lintWarns.length) svg.dataset.lint = lintWarns.join('|');

/* 箭头 marker：按颜色懒创建 */
const markers = {};
function marker(c) {
  if (markers[c]) return markers[c];
  const id = 'mk' + Object.keys(markers).length;
  let defs = svg.querySelector('defs'); if (!defs) { defs = mk('defs', {}); svg.prepend(defs); }
  defs.insertAdjacentHTML('beforeend', `<marker id="${id}" viewBox="0 0 9 9" refX="8" refY="4.5" markerWidth="7" markerHeight="7" orient="auto"><path d="M0.5,1 L8,4.5 L0.5,8 Z" fill="${c}"/></marker>`);
  return markers[c] = id;
}

/* 图标：浅色底块 + Lucide 线性图标；名称不在图标库里 → 几何块降级 */
function drawIcon(cx, cy, color, kind) {
  R(cx - IB/2, cy - IB/2, IB, IB, mix(color, '#FFFFFF', 0.88), 5);
  if (ICONS[kind]) {
    const s = 15, g = mk('g', { 'data-icon': kind, transform: `translate(${cx - s/2},${cy - s/2}) scale(${s/24})`,
      fill: 'none', stroke: color, 'stroke-width': 2, 'stroke-linecap': 'round', 'stroke-linejoin': 'round' });
    g.innerHTML = ICONS[kind]; add(g); return;
  }
  const r = 7;
  if (kind === 'sq')   add(mk('rect', { x:cx-r*.4, y:cy-r*.4, width:r*.8, height:r*.8, rx:1.5, fill:color }));
  else if (kind === 'ring') add(mk('circle', { cx, cy, r:r*.45, fill:'none', stroke:color, 'stroke-width':1.6 }));
  else if (kind === 'tri')  add(mk('path', { d:`M${cx},${cy-r*.45} L${cx+r*.45},${cy+r*.35} L${cx-r*.45},${cy+r*.35} Z`, fill:color }));
  else add(mk('circle', { cx, cy, r:r*.4, fill:color }));
}

/* 标签断行：有空格按空格断，否则 ≤4 字一行、多行时均分 */
function tagLines(s) {
  s = String(s);
  if (s.includes(' ')) return s.split(' ');
  const n = Math.ceil(s.length / 4), per = Math.ceil(s.length / n), out = [];
  for (let i = 0; i < s.length; i += per) out.push(s.slice(i, i + per));
  return out;
}

/* ---------- 绘制 ---------- */
function drawTag(n) {
  R(n.x, n.y, TAG_W, n.h, mix(n.c, '#FFFFFF', 0.9), 6);
  const lines = tagLines(n.tag[0]), sub = n.tag[1];
  const blockH = lines.length * 16 + (sub ? 14 : 0);
  let y = n.y + (n.h - blockH) / 2 + 12;
  lines.forEach(s => { TX(n.x + TAG_W/2, y, s, FS.body, n.c, 700, 'middle'); y += 16; });
  if (sub) TX(n.x + TAG_W/2, y + 1, sub, FS.note, '#8A94A6', 400, 'middle');
}

function drawBox(n) {
  if (n.tag) drawTag(n);
  if (n.depth > 0 && !n.bare) {
    const bx = n.x + tagOf(n), bw = n.w - tagOf(n), d = Math.min(n.depth, 3);
    const fill = n.tint ? mix(n.c, '#FFFFFF', 0.95) : DEPTH_BG[d];
    const ex = (d >= 3 || n.dashed)
      ? { stroke: n.tint ? mix(n.c, '#FFFFFF', 0.8) : '#D3DCEA', 'stroke-width':1, 'stroke-dasharray':'3 3' } : {};
    R(bx, n.y, bw, n.h, fill, d === 1 ? 8 : 6, ex);
    if (n.title) TX(bx + PAD + 2, n.y + PAD + 12, n.title, FS.body, n.c, 700);
  }
  n.children.forEach(k => isBox(k) ? drawBox(k) : drawLeaf(k));
  /* 流水线箭头：单行横箭头；flow+wrap 蛇形——行内按实际左右关系画，
     行末→下行首在同侧对齐，回折是一条竖线 */
  if (n.flow && (n.wrap || n.dir === 'row')) {
    const id = marker(n.c);
    const cols = n.wrap || n.children.length;
    const rows = [];
    for (let r = 0; r * cols < n.children.length; r++)
      rows.push(n.children.slice(r * cols, (r + 1) * cols));
    rows.forEach((row, ri) => {
      row.slice(0, -1).forEach((a, i) => {
        const b = row[i + 1], y = a.y + a.h / 2;
        const leftward = a.x > b.x;          // 奇数行翻转后 a 在 b 右侧
        add(mk('line', {
          x1: leftward ? a.x - 3 : a.x + a.w + 3, y1: y,
          x2: leftward ? b.x + b.w + 3 : b.x - 3, y2: y,
          stroke: n.c, 'stroke-width': 1.5, 'marker-end': `url(#${id})`
        }));
      });
      if (ri < rows.length - 1) {
        /* 蛇形回折：按两卡**中心**对齐——中心重合则纯竖线；
           末行不足 wrap 列时中心略错开，在行间隙里走一小段横移再落下（不贴边线） */
        const a = row[row.length - 1], b = rows[ri + 1][0];
        const y1 = a.y + a.h, y2 = b.y, ym = (y1 + y2) / 2;
        const x1 = a.x + a.w / 2, x2 = b.x + b.w / 2;
        const d = Math.abs(x1 - x2) < 2
          ? `M${x1},${y1} V${y2 - 3}`
          : `M${x1},${y1} V${ym} H${x2} V${y2 - 3}`;
        add(mk('path', {
          d, fill: 'none', stroke: n.c, 'stroke-width': 1.5,
          'marker-end': `url(#${id})`, 'stroke-linejoin': 'round'
        }));
      }
    });
  }
}

function drawLeaf(n) {
  if (n.flat) {                                         /* 平铺条：图标 + 文字在格内居中 */
    const tw = estW(n.t, FS.body), total = (n.kind ? IB + 8 : 0) + tw;
    let x = n.x + (n.w - total) / 2; const cy = n.y + n.h / 2;
    if (n.kind) { drawIcon(x + IB/2, cy, n.c, n.kind); x += IB + 8; }
    TX(x, cy + 4.5, n.t, FS.body, TEXT, 500);
    return;
  }
  R(n.x, n.y, n.w, n.h, '#FFFFFF', 6, { stroke:CARD_LINE, 'stroke-width':1 });
  const bh = 16 + 14 * n.d.length;                      /* 内容块垂直居中（拉伸后也居中） */
  const top = n.y + (n.h - bh) / 2;
  let tx = n.x + 12;
  if (n.kind) { drawIcon(n.x + 12 + IB/2, n.d.length ? top + 8 : n.y + n.h/2, n.c, n.kind); tx += IB + 9; }
  TX(tx, top + 12, n.t, FS.body, TEXT, 600);
  n.d.forEach((s, i) => TX(tx, top + 28 + 14*i, s, FS.note, SUB));
}

/* 关系线：直角折线，颜色 = 起点身份色；自动挑不穿卡片的走法 */
function drawLinks() {
  if (!LINKS.length) return;
  const byId = {};
  (function walk(n) { if (n.id) byId[n.id] = n; if (isBox(n)) n.children.forEach(walk); })(root);
  LINKS.forEach(([a, b, label, dashed]) => {
    const A = byId[a], B = byId[b];
    if (!A || !B) throw new Error('LINKS 找不到 id：' + (A ? b : a));
    let d, lx, ly;
    const hitsOf = path => {
      const pts = []; let px = 0, py = 0;
      path.match(/[MHV][^MHV]+/g).forEach(s => { const v = s.slice(1).split(',').map(Number);
        if (s[0] === 'M') { px = v[0]; py = v[1]; } else if (s[0] === 'H') px = v[0]; else py = v[0];
        pts.push([px, py]); });
      const hit = [];
      (function walk(n) { if (isBox(n)) return n.children.forEach(walk);
        if (n === A || n === B) return;
        for (let i = 1; i < pts.length; i++) {
          const [ax, ay] = pts[i-1], [bx2, by2] = pts[i];
          if (Math.max(ax, bx2) > n.x + 1 && Math.min(ax, bx2) < n.x + n.w - 1 &&
              Math.max(ay, by2) > n.y + 1 && Math.min(ay, by2) < n.y + n.h - 1) { hit.push(n.t); break; }
        } })(root);
      return hit;
    };
    if (A.y + A.h <= B.y || B.y + B.h <= A.y) {          // 上下关系
      const dn = A.y < B.y, x1 = A.x + A.w/2, x2 = B.x + B.w/2;
      const y1 = dn ? A.y + A.h : A.y, y2 = dn ? B.y - 1 : B.y + B.h + 1;
      const yb = dn ? B.y - 12 : B.y + B.h + 12, ay = A.y + A.h/2;
      const cands = [
        [`M${x1},${y1} V${(y1 + y2) / 2} H${x2} V${y2}`, x2 + 6, (y1 + y2) / 2 + 14],
        [`M${A.x + A.w},${ay} H${A.x + A.w + 5} V${yb} H${x2} V${y2}`, A.x + A.w + 9, yb - 5],
        [`M${A.x},${ay} H${A.x - 5} V${yb} H${x2} V${y2}`, x2 + 6, yb - 5],
      ];
      [d, lx, ly] = cands.find(c => !hitsOf(c[0]).length) || cands[0];
    } else {                                              // 左右关系
      const rt = A.x < B.x, y1 = A.y + A.h/2, y2 = B.y + B.h/2;
      const x1 = rt ? A.x + A.w : A.x, x2 = rt ? B.x - 1 : B.x + B.w + 1, xm = (x1 + x2) / 2;
      const lw = estW(label || '', FS.note);
      const yd = Math.max(A.y + A.h, B.y + B.h) + 5, yu = Math.min(A.y, B.y) - 5;
      const ax = A.x + A.w/2, bx2 = B.x + B.w/2;
      const cands = [
        [`M${x1},${y1} H${xm} V${y2} H${x2}`, xm - lw/2, Math.min(y1, y2) - 6],
        [`M${ax},${A.y + A.h} V${yd} H${bx2} V${B.y + B.h + 1}`, (ax + bx2)/2 - lw/2, yd + 11],
        [`M${ax},${A.y} V${yu} H${bx2} V${B.y - 1}`, (ax + bx2)/2 - lw/2, yu - 3],
      ];
      [d, lx, ly] = cands.find(c => !hitsOf(c[0]).length) || cands[0];
    }
    const hit = hitsOf(d);
    if (hit.length) svg.dataset.linkHits = (svg.dataset.linkHits ? svg.dataset.linkHits + '|' : '') + `${a}→${b} 穿过 ${hit.join('、')}`;
    add(mk('path', { d, fill:'none', stroke:A.c, 'stroke-width':1.5, 'stroke-linejoin':'round',
      ...(dashed ? { 'stroke-dasharray':'5 4' } : {}), 'marker-end':`url(#${marker(A.c)})` }));
    if (label) {
      const w = estW(label, FS.note);
      R(lx - 3, ly - 10, w + 6, 13, '#FFFFFF', 3, { opacity:.92 });
      TX(lx, ly, label, FS.note, A.c, 500);
    }
  });
}

if (DIAGRAM.title)    TX(M, 52, DIAGRAM.title, FS.title, INK, 700);
if (DIAGRAM.subtitle) TX(M, 76, DIAGRAM.subtitle, FS.note, SUB);
drawBox(root);
drawLinks();
